alter table public.categories enable row level security;alter table public.job_descriptions enable row level security;alter table public.resumes enable row level security;alter table public.tailoring_jobs enable row level security;
create policy "authenticated read active categories" on public.categories for select to authenticated using(active=true);
create policy "owners read jobs" on public.job_descriptions for select to authenticated using((select auth.uid())=user_id);create policy "owners insert jobs" on public.job_descriptions for insert to authenticated with check((select auth.uid())=user_id);create policy "owners update jobs" on public.job_descriptions for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "owners delete jobs" on public.job_descriptions for delete to authenticated using((select auth.uid())=user_id);
create policy "owners read resumes" on public.resumes for select to authenticated using((select auth.uid())=user_id);create policy "owners insert resumes" on public.resumes for insert to authenticated with check((select auth.uid())=user_id);create policy "owners update resumes" on public.resumes for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy "owners delete resumes" on public.resumes for delete to authenticated using((select auth.uid())=user_id);
create policy "owners read queue" on public.tailoring_jobs for select to authenticated using((select auth.uid())=user_id);create policy "owners insert queue" on public.tailoring_jobs for insert to authenticated with check((select auth.uid())=user_id and exists(select 1 from public.job_descriptions j where j.id=job_description_id and j.user_id=(select auth.uid())) and exists(select 1 from public.resumes r where r.id=resume_id and r.user_id=(select auth.uid())));create policy "owners update queue" on public.tailoring_jobs for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id and exists(select 1 from public.job_descriptions j where j.id=job_description_id and j.user_id=(select auth.uid())) and exists(select 1 from public.resumes r where r.id=resume_id and r.user_id=(select auth.uid())));create policy "owners delete queue" on public.tailoring_jobs for delete to authenticated using((select auth.uid())=user_id);
revoke all on public.categories,public.job_descriptions,public.resumes,public.tailoring_jobs from anon;grant select on public.categories to authenticated;grant select,insert,update,delete on public.job_descriptions,public.resumes,public.tailoring_jobs to authenticated;
